"""Materialising reference evaluator for the supported expression subset."""
import ast

MAX = (1 << 63) - 1

class Bad(Exception): pass

def fp(data):
    h = 0
    for b in data:
        h = (h*257 + b + 1) & ((1 << 64) - 1)
    return {'n': len(data), 'h': '%016x' % h}

def depth(node):
    st = [(node,0)]; m = 0
    while st:
        n,d = st.pop()
        m = max(m,d)
        for c in ast.iter_child_nodes(n): st.append((c,d+1))
    return m

def parse(source):
    try:
        tree = ast.parse(source, mode='eval')
    except Exception:
        raise Bad()
    if depth(tree.body) > 128: raise Bad()
    return tree.body

def ev(node, env):
    k = type(node)
    if k is ast.Constant:
        v = node.value
        if v is None or isinstance(v, bool): raise Bad()
        if isinstance(v, int):
            if v < 0 or v > MAX: raise Bad()
            return v
        if isinstance(v, str):
            try: return v.encode('utf8')
            except UnicodeEncodeError: raise Bad()
        if isinstance(v, bytes): return v
        raise Bad()
    if k is ast.Name:
        if node.id not in env: raise Bad()
        return env[node.id]
    if k is ast.BinOp:
        op = type(node.op)
        if op is ast.Add:
            l = ev(node.left, env); r = ev(node.right, env)
            if isinstance(l,int) or isinstance(r,int): raise Bad()
            if len(l)+len(r) > MAX: raise Bad()
            return l+r
        if op is ast.Mult:
            l = ev(node.left, env); r = ev(node.right, env)
            li = isinstance(l,int); ri = isinstance(r,int)
            if li == ri: raise Bad()
            seq, cnt = (r,l) if li else (l,r)
            if cnt < 0 or cnt > MAX: raise Bad()
            if len(seq)*cnt > MAX: raise Bad()
            return seq*cnt
        raise Bad()
    if k is ast.Subscript:
        v = ev(node.value, env)
        if isinstance(v,int): raise Bad()
        sl = node.slice
        if type(sl) is not ast.Slice or sl.step is not None: raise Bad()
        lo = 0 if sl.lower is None else const(sl.lower)
        hi = len(v) if sl.upper is None else const(sl.upper)
        if lo < 0 or hi < lo or hi > len(v): raise Bad()
        return v[lo:hi]
    raise Bad()

def const(node):
    if type(node) is not ast.Constant: raise Bad()
    v = node.value
    if isinstance(v,bool) or not isinstance(v,int): raise Bad()
    if v < 0 or v > MAX: raise Bad()
    return v
