import sys, random, json, ast
sys.path.insert(0,'/workspace/project')
import main as impl
import refexpr

LITS = ["b'a'", "b'abc'", "'x'", "'é'", "b''", "''", "0", "1", "5", "100", "2**0"]

def gen(rng, names, depth=0):
    r = rng.random()
    if depth > 3 or r < 0.3:
        if names and rng.random() < 0.4:
            return rng.choice(names)
        return rng.choice(LITS)
    if r < 0.6:
        return "(%s + %s)" % (gen(rng, names, depth+1), gen(rng, names, depth+1))
    if r < 0.8:
        return "(%s * %d)" % (gen(rng, names, depth+1), rng.randint(0,4))
    base = gen(rng, names, depth+1)
    lo = rng.randint(0, 6); hi = lo + rng.randint(0, 6)
    style = rng.random()
    if style < 0.4:
        return "(%s)[%d:%d]" % (base, lo, hi)
    if style < 0.7:
        return "(%s)[%d:]" % (base, lo)
    if style < 0.9:
        return "(%s)[:%d]" % (base, hi)
    return "(%s)[%d:%d:]" % (base, lo, hi)

bad = 0
for seed in range(int(sys.argv[1]) if len(sys.argv)>1 else 500):
    rng = random.Random(seed)
    ndefs = rng.randint(1,4)
    names = []
    defs = []
    for i in range(ndefs):
        name = 'D%d' % i
        expr = gen(rng, names)
        defs.append([name, expr])
        names.append(name)
    doc = {'seed':'s','definitions':defs,'timeout_ms':10,
           'cases':[{'name':'a','frames':[{'Type':'data','data_to_transfered':'{{D%d}}'%(ndefs-1),'End_Stream':True}],
                     'expect':{'method':'GET','target':'/','host':'h'}}],
           'events':[],'channels':[]}
    # reference
    env = {}
    refbad = False
    for name, expr in defs:
        try:
            body = refexpr.parse(expr)
            value = refexpr.ev(body, env)
            if isinstance(value, int): refbad = True; break
            env[name] = value
        except refexpr.Bad:
            refbad = True; break
    try:
        out = impl.run(doc)
    except Exception as e:
        out = {'error':'input'}
    if refbad:
        if 'error' not in out:
            print('EXPECTED ERROR seed', seed, defs); bad += 1
        continue
    if 'error' in out:
        print('UNEXPECTED ERROR seed', seed, defs, out); bad += 1; continue
    got = out['cases'][0]['sent']
    want = refexpr.fp(env[defs[-1][0]])
    # the receipt is time+stream+kind+len+data+end
    data = env[defs[-1][0]]
    receipt = (0).to_bytes(8,'big')+(0).to_bytes(4,'big')+b'D'+len(data).to_bytes(8,'big')+data+b'\x01'
    want = refexpr.fp(receipt)
    if got != want:
        print('MISMATCH seed', seed, defs, got, want); bad += 1
    if bad > 4: break
print('done, failures:', bad)
